import java.util.*; class Solution { public List<String> addOperators(String num, int target) { List<String> result = new ArrayList<>(); if (num == null || num.length() == 0) return result; backtrack(result, new StringBuilder(), num, target, 0, 0, 0); return result; } private void backtrack(List<String> result, StringBuilder sb, String num, int target, int index, long currentVal, long lastOperand) { if (index == num.length()) { if (currentVal == target) { result.add(sb.toString()); } return; } for (int i = index; i < num.length(); i++) { if (i != index && num.charAt(index) == '0') break; long val = Long.parseLong(num.substring(index, i + 1)); int len = sb.length(); if (index == 0) { sb.append(val); backtrack(result, sb, num, target, i + 1, val, val); sb.setLength(len); } else { sb.append("+").append(val); backtrack(result, sb, num, target, i + 1, currentVal + val, val); sb.setLength(len); sb.append("-").append(val); backtrack(result, sb, num, target, i + 1, currentVal - val, -val); sb.setLength(len); sb.append("*").append(val); backtrack(result, sb, num, target, i + 1, currentVal - lastOperand + (lastOperand * val), lastOperand * val); sb.setLength(len); } } } }